"use strict";

var _filters = require("../filters");
describe('filters', function () {
  describe('addOptionToFilter', function () {
    test('should add options', function () {
      var option = {
        id: 'id'
      };
      var setter = jest.fn();
      (0, _filters.addOptionToFilter)('', setter, [], option);
      expect(setter).toHaveBeenCalledWith([option]);
    });
    test('should handle one option', function () {
      var option = {
        id: 'id'
      };
      var setter = jest.fn();
      (0, _filters.addOptionToFilter)(_filters.FILTER_NAMES.locationIds, setter, [{
        id: 'id2'
      }], option, true);
      expect(setter.mock.calls[0][0]).toEqual([option]);
      (0, _filters.addOptionToFilter)(_filters.FILTER_NAMES.listTemplateIds, setter, [{
        id: 'id3'
      }], option, true);
      expect(setter.mock.calls[1][0]).toEqual([option]);
    });
    test('should handle non array', function () {
      var option = {
        id: 'id'
      };
      var setter = jest.fn();
      (0, _filters.addOptionToFilter)('', setter, undefined, option);
      expect(setter).toHaveBeenCalledWith([option]);
    });
  });
  describe('getSelectedOptionsText', function () {
    it('return All Lists for empty', function () {
      expect((0, _filters.getSelectedOptionsText)([], 'List')).toEqual('All Lists');
    });
    it('return 1 Location', function () {
      var selected = [{
        label: 'Utah'
      }];
      expect((0, _filters.getSelectedOptionsText)(selected, 'Location')).toEqual('1 Location');
    });
    it('return 2 Lists', function () {
      var selected = [{
        label: 'Utah'
      }, {
        label: 'Lehi'
      }];
      expect((0, _filters.getSelectedOptionsText)(selected, 'List')).toEqual('2 Lists');
    });
    it('returns Utah', function () {
      var selected = [{
        label: 'Utah'
      }];
      expect((0, _filters.getSelectedOptionsText)(selected, 'Location', true)).toEqual('Utah');
    });
    it('returns "Select Location" for empty single selection', function () {
      expect((0, _filters.getSelectedOptionsText)([], 'Location', true)).toEqual('Select Location');
    });
    test('should show count if provided', function () {
      expect((0, _filters.getSelectedOptionsText)([], 'Monkey', false, 5)).toEqual('All Monkeys (5)');
    });
  });
  describe('removeOptionFromFilter', function () {
    test('should remove option', function () {
      var id = 'id';
      var options = [{
        id: id
      }];
      var setter = jest.fn();
      (0, _filters.removeOptionFromFilter)('', setter, options, id);
      expect(setter).toHaveBeenCalledWith([]);
    });
  });
});